def f(g):
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]; H,W=len(g),len(g[0])
    out=[[bg]*W for _ in range(H)]
    for r in range(H-1):
        for c,x in enumerate(g[r]):
            if x!=bg: out[r+1][c]=x
    return out
